const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','diagrams-data.js','exploration-data.js','progression-data.js','progression-engine.js','departure.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window,{tasks,hubs}=w.PHOENIX_ROUTE,engine=w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,tasks,hubs),state={progress:engine.init(),completed:{}};return {w,tasks,engine,state,build:()=>w.PhoenixDeparture.build({state,engine,tasks})};}
test('unrecorded departure risks ask for verification without writing progress',()=>{const x=setup(),before=JSON.stringify(x.state),v=x.build();assert.equal(v.risks.length,3);assert.ok(v.risks.every(r=>r.unknown&&r.status==='Not recorded — check in game'));assert.equal(v.unknowns.length,4);assert.equal(v.knownOpen.length,0);assert.equal(JSON.stringify(x.state),before);});
test('unrecorded departure-sensitive quest still produces a cutoff reminder',()=>{const x=setup(),v=x.build();assert.equal(v.knownOpen.length,0);assert.equal(v.unknowns.length,4);assert.ok(v.warningEligible.some(r=>r.id==='q-firestarter'));assert.ok(v.warningEligible.some(r=>r.id==='q-missing'));assert.ok(v.warningEligible.some(r=>r.id==='q-death'));assert.ok(v.warningEligible.some(r=>r.id==='poi-4'));assert.equal(v.warningEligible.length,4);});
test('recorded completion, failure and departure suppress applicable risk pulses',()=>{const x=setup();x.state.progress.legacy['q-firestarter']=true;x.state.progress.failed['q-missing']=true;const v=x.build();assert.ok(!v.warningEligible.some(r=>['q-firestarter','q-missing'].includes(r.id)));assert.ok(v.failed.some(r=>r.id==='q-missing'));assert.ok(v.completed.some(r=>r.id==='q-firestarter'));x.state.progress.manual.departed=true;assert.ok(x.build().departed);assert.ok(!x.build().warningEligible.some(r=>r.kind==='cutoff-unknown'));});
test('skull uses its earlier cutoff and returns after story correction',()=>{const x=setup();assert.ok(x.build().skull.unknown);x.state.progress.manual.griffin=true;const v=x.build();assert.equal(v.skull.kind,'cutoff-unknown');assert.match(v.skull.status,/Earlier cutoff/);assert.ok(!v.warningEligible.some(r=>r.id==='poi-4'));delete x.state.progress.manual.griffin;assert.equal(x.build().skull.unknown,true);x.state.completed['poi-4']=true;assert.equal(x.build().skull.completed,true);assert.equal(x.build().skull.unknown,false);});
test('checklist contains only skull and three quests; optional groups removed',()=>{const x=setup(),v=x.build();assert.equal(v.ordered.length,4);assert.equal(v.ordered[0].id,'poi-4');assert.equal(v.ordered.slice(1).map(r=>r.id).join(','),'q-firestarter,q-missing,q-death');assert.ok(!v.groups);});
test('known-open and unknown counts stay distinct; no double-counting',()=>{const x=setup();x.state.progress.legacy['q-firestarter']=true;x.state.progress.failed['q-missing']=true;const v=x.build();assert.equal(v.knownOpen.length,0);assert.ok(v.unknowns.length>=1);assert.ok(v.failed.length===1);assert.ok(v.completed.length===1);assert.ok(!v.warningEligible.some(r=>r.unknown&&r.kind==='cutoff-unknown'));});
test('warning trigger is limited to departure walkthrough stages',()=>{const x=setup(),at=x.w.PhoenixDeparture.atStep;assert.ok(at('q-lilac','4'));assert.ok(at('q-incident','1'));assert.ok(at('q-incident','2'));assert.ok(!at('q-lilac','3'));assert.ok(!at('activity-departure-review','1'));assert.ok(!at('home','4'));});
